import urllib.request, json
url = "https://api.github.com/repos/topology-tool-kit/ttk-data/git/trees/dev?recursive=1"
req = urllib.request.Request(url, headers={"User-Agent":"curl"})
try:
    d = json.load(urllib.request.urlopen(req, timeout=20))
    for e in d.get('tree', []):
        p = e['path']
        if any(k in p.lower() for k in ['brain','tensor','wedge','trisector']):
            print(p)
except Exception as e:
    print("ERR", e)
EOF
